package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.IOException;
import java.util.*;
import static it.cavallium.rockserver.distributed.ratis.RatisSnapshotCohortRpc.*;

/** Borrowed routed clients; every request stays on its frozen voter rather than choosing another endpoint. */
public final class RatisSnapshotCohortClient implements RatisDatabaseBackupDriver.CohortTransport {
    private record Pool(UUID node,UUID incarnation,UUID process,UUID pool){}
    private final Map<UUID,RatisRoutedClient> routed;private final java.util.function.Function<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozenCapture;private final Map<UUID,RatisRoutedClient.SnapshotTarget> targets=new HashMap<>();
    public RatisSnapshotCohortClient(Map<UUID,RatisRoutedClient> routed,java.util.function.Function<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozenCapture){this.routed=Map.copyOf(routed);this.frozenCapture=Objects.requireNonNull(frozenCapture);}
    private RatisRoutedClient client(UUID group)throws IOException {var client=routed.get(group);if(client==null)throw new IOException("Backup group has no declared routed client");return client;}
    private static Capabilities supported(RatisRoutedClient.SnapshotTarget target,long ttl)throws IOException {var cap=target.cohort();if(cap==null)throw new IOException("Original owner does not support native cohort capture");var peer=target.replica();if(!cap.nodeId().equals(peer.nodeId()) || !cap.nodeIncarnation().equals(peer.nodeIncarnation()) || ttl>cap.maximumReadonlyMillis() || ttl>cap.poolMaximumAgeMillis() || cap.currentCohorts()>=cap.maximumCohorts() || cap.registryEntries()>=cap.registryMaximumEntries() || cap.registryBytes()>=cap.registryMaximumBytes() || cap.poolPins()>=cap.poolMaximumPins() || cap.poolBytes()>=cap.poolMaximumBytes() || cap.poolNextEstimatedBytes()>cap.poolMaximumBytes()-cap.poolBytes() || cap.poolFreeBytes()<cap.poolMinimumFreeBytes())throw new IOException("Declared backup exceeds actual owner/pool capabilities");return cap;}
    @Override public void requireSupported(DatabaseBackupDefinition definition,RatisDatabaseBackupDriver.Policy policy)throws IOException {
        var pools=new HashMap<Pool,Integer>();var bytes=new HashMap<Pool,Long>();var definitions=new HashMap<Pool,Set<UUID>>();for(var domain:definition.domains())for(var fence:domain.fences())for(var member:fence.participants()) {var target=client(member.groupId()).snapshotTarget(fence,member.groupId());var cap=supported(target,policy.retention().toMillis());long charge=RatisSnapshotPins.TOMBSTONE_BYTES+(long)fence.encode().length+RangeMutationHistory.accountedScopeBytes(member.scope());if(charge>cap.registryMaximumBytes()-cap.registryBytes())throw new IOException("Declared backup registry metadata exceeds admission");var pool=new Pool(cap.nodeId(),cap.nodeIncarnation(),cap.processIncarnation(),cap.poolId());pools.merge(pool,1,Integer::sum);bytes.merge(pool,124L,Long::sum);if(definitions.computeIfAbsent(pool,k->new HashSet<>()).add(fence.fenceId()))bytes.merge(pool,4L+fence.encode().length,Long::sum);}
        if(pools.size()>policy.maximumCohorts())throw new IOException("Declared backup cohort count exceeds policy");for(var count:pools.values())if(count>MAX_MEMBERS)throw new IOException("Declared pool cohort exceeds native member bound");for(var size:bytes.values())if(size+72>MAX_REQUEST_BYTES-ScopedTransactionRpc.HEADER_BYTES)throw new IOException("Declared cohort exceeds request frame budget");
    }
    @Override public List<RatisDatabaseBackupJournal.CohortRequest> qualify(DatabaseBackupDefinition definition,Map<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozen,RatisDatabaseBackupDriver.Policy policy)throws IOException {
        var pools=new LinkedHashMap<Pool,List<RatisDatabaseBackupJournal.Member>>();for(var entry:frozen.entrySet().stream().sorted(Map.Entry.comparingByKey(RangeDirectoryCodec.UUID_ORDER)).toList()){var group=entry.getKey();var prepared=entry.getValue();var owner=RatisSnapshotOwner.decode(client(group).cohortQuery(prepared.target(),OWNER,prepared.request().encode()));if(!owner.groupId().equals(group) || owner.rangeEpoch()!=prepared.target().descriptor().rangeEpoch() || !Arrays.equals(owner.schemaDigest(),prepared.request().fence().participant(group).schemaDigest()) || !owner.incarnation().equals(prepared.request().owner()) || !owner.peerId().equals(prepared.target().replica().peerId()))throw new IOException("Fresh cohort qualification changed original owner");var cap=owner.cohort();if(cap==null || !cap.nodeId().equals(prepared.target().replica().nodeId()) || !cap.nodeIncarnation().equals(prepared.target().replica().nodeIncarnation()) || prepared.request().ttl().toMillis()>cap.maximumReadonlyMillis() || prepared.request().ttl().toMillis()>cap.poolMaximumAgeMillis())throw new IOException("Fresh native cohort capabilities changed");var pool=new Pool(cap.nodeId(),cap.nodeIncarnation(),cap.processIncarnation(),cap.poolId());pools.computeIfAbsent(pool,k->new ArrayList<>()).add(new RatisDatabaseBackupJournal.Member(prepared.request().fence().fenceId(),group,prepared.request().snapshotId(),prepared.request().owner(),prepared.target().replica().replicaId(),prepared.request().ttl().toMillis(),hash(prepared.bytes())));targets.put(group,prepared.target());}
        if(pools.size()>policy.maximumCohorts())throw new IOException("Qualified cohort count exceeds policy");var requests=new ArrayList<RatisDatabaseBackupJournal.CohortRequest>();for(var entry:pools.entrySet()){var pool=entry.getKey();var request=new RatisDatabaseBackupJournal.CohortRequest(UUID.randomUUID(),pool.incarnation,pool.process,pool.pool,entry.getValue());var captures=new HashMap<UUID,RatisSnapshotCaptureRequest>();for(var member:request.members())captures.put(member.groupId(),frozen.get(member.groupId()).request());request(new Request(request,captures));requests.add(request);}return List.copyOf(requests);
    }
    @Override public Map<UUID,RatisSnapshotCaptureRequest.Result> capture(RatisDatabaseBackupJournal.CohortRequest cohort,Map<UUID,RatisRoutedClient.PreparedSnapshotCapture> frozen)throws IOException {var captures=new HashMap<UUID,RatisSnapshotCaptureRequest>();for(var member:cohort.members()){var prepared=frozen.get(member.groupId());if(prepared==null)throw new IOException("Frozen cohort member absent");captures.put(member.groupId(),prepared.request());targets.put(member.groupId(),prepared.target());}var request=new Request(cohort,captures);var reply=call(cohort,CAPTURE,request(request));if(reply.phase()==Phase.PENDING || reply.phase()==Phase.DRAINING)throw new IOException("Original cohort capture is still "+reply.phase());if(reply.phase()!=Phase.CAPTURED)throw new RatisSnapshotLostException("Original cohort capture is "+reply.phase());var expected=cohort.members().stream().map(RatisDatabaseBackupJournal.Member::groupId).collect(java.util.stream.Collectors.toSet());if(!reply.captures().keySet().equals(expected))throw new IOException("Cohort reply coverage changed");for(var member:cohort.members()){var token=reply.captures().get(member.groupId()).token();if(!token.ownerIncarnation().equals(member.owner()) || !token.snapshotId().equals(member.snapshotId()))throw new IOException("Cohort reply changed original member pin");}return reply.captures();}
    private Reply call(RatisDatabaseBackupJournal.CohortRequest request,int kind,byte[] body)throws IOException {var group=request.members().getFirst().groupId();var target=targets.get(group);if(target==null){var member=request.members().getFirst();var frozen=frozenCapture.apply(group);if(frozen==null || !Arrays.equals(hash(frozen.bytes()),member.preparedDigest()) || !frozen.request().owner().equals(member.owner()) || !frozen.target().replica().replicaId().equals(member.replica()))throw new IOException("Original cohort voter route is not restored");target=frozen.target();targets.put(group,target);}try{return reply(client(group).cohortQuery(target,kind,body),reference(request));}catch(IllegalArgumentException invalid){throw new IOException("Invalid original cohort reply",invalid);}}
    @Override public void requireLive(RatisDatabaseBackupJournal.CohortRequest request,Map<UUID,SnapshotFenceStatus.Capture> original)throws IOException {var reply=call(request,STATE,reference(reference(request)));if(reply.phase()!=Phase.CAPTURED)throw new RatisSnapshotLostException("Original cohort is no longer live");for(var member:request.members())if(!Objects.equals(original.get(member.groupId()),reply.captures().get(member.groupId()).token()))throw new RatisSnapshotLostException("Cohort changed original pin token");}
    @Override public void cancelAndDrain(RatisDatabaseBackupJournal.CohortRequest request)throws IOException {var reply=call(request,CANCEL,reference(reference(request)));if(reply.phase()!=Phase.RELEASED && reply.phase()!=Phase.GONE)throw new IOException("Actual cohort capture/export/native cleanup remains active");}
}
